use ql_benches::{format_markdown_table, run_all_benchmarks};
use std::fs;
use std::path::PathBuf;

fn main() {
    let rows = run_all_benchmarks(5);
    let report = format_markdown_table(&rows);
    println!("{report}");
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("BENCHMARK_RESULTS.md");
    let document = format!(
        "# ql-rs Quantitative Performance Benchmarks\n\nGenerated by `cargo +nightly bench -p ql-benches`.\n\n{report}"
    );
    fs::write(path, document).expect("write benchmark report");
}
